# -*- coding: utf-8 -*-
"""原理讲解：slice_1.json 索引 91-135（共 45 条），键为题号 num。"""

EXP = {
    "20221": r"""此题需看图，图上若在混频器之前有射频预选、混频器配本机振荡器、后面跟着固定频率的中频放大与包络检波，就是超外差 AM 接收机，hétérodyne（外差）的含义正是「带中频」。判据是本振加混频加固定中频这三件套；若根本没有中频级，直接把天线信号检波，那是直放式（récepteur direct）接收机；出现限幅器与鉴频器则是 FM；画着话筒的才是发射机。""",
    "20223": r"""解调方式决定能收什么信号：包络检波器（détecteur d'enveloppe，二极管加 RC 低通）只跟随幅度的起伏，只能还原调幅；听 BLU 与 CW 必须在检波处注入一个本机载波做乘积检波，听 FM 要限幅器加鉴频器。口诀是：包络检波配调幅，乘积检波配单边带与等幅报，鉴频器配调频。既然用的是包络检波，对应调制类型就是 AM。""",
    "20229": r"""此题需看图，图上给出已调波包络的最大值与最小值（官方按 \(U_{\max}=10\ \mathrm{V}\)、\(U_{\min}=5\ \mathrm{V}\) 计算）。调制率就是包络起伏的相对深度：\(k=\frac{U_{\max}-U_{\min}}{U_{\max}+U_{\min}}=\frac{10-5}{10+5}=\frac{5}{15}\)，约得 0.33，即 33%。这道题的思路就是量出包络的最高点与最低点，再按公式相减、相加。起伏越大调制越深、话音越响，但超过 100% 就会削波失真，所以 150% 不可能出现。""",
    "20230": r"""调制率 \(k=\frac{U_{\max}-U_{\min}}{U_{\max}+U_{\min}}\) 最大只能等于 1。当 \(U_{\min}=0\) 时包络刚好碰到零轴，再加深就出现过调制，包络被削平、产生大量杂散边带与严重失真，发射带宽也会超标。因此上限是 100%；工程上留余量常按 80% 左右工作，但问「可以施加的最大值」就是 100%。""",
    "20231": r"""CAG（自动增益控制）从检波后的直流分量取样，去控制 RF 与 FI 级的增益，使强台弱台给出大致相同的音频电平，并防止中频级被强信号饱和削波，S 表指示的就是这个电压。官方注释指出本题选项不严谨：严格说它代替的是手动 RF 增益旋钮，而不是音频音量——信号在检波前已被削波时，拧音量钮已无法补救。标准答案仍按题给：代替手动音频功率控制。""",
    "20301": r"""串联电路电流处处相同，各电阻上的电压与阻值成正比，总电压等于各段电压之和。官方注释取 \(I=2\ \mathrm{mA}\)：\(U_{R1}=1000\times0.002=2\ \mathrm{V}\)，再加另一只电阻上的 3 V，得 \(U_T=5\ \mathrm{V}\)。⚠️待核：题干写的 57 kΩ 与注释口径不自洽（按 57 kΩ 分压算不出 5 V），四个选项中只有 5 V 符合「电压相加」这一思路。""",
    "20302": r"""二极管正向导通就是 P 区接正、N 区接负，电流由 P 流向 N，这条正确。导通时结电阻很小而非很大；接正极的电极是阳极（P 侧），阴极在 N 侧、导通时接负极，所以「阴极接 +」错。硅二极管门槛电压约 0.6~0.7 V，0.3 V 是锗管的数值，故第四句也错。""",
    "20308": r"""此题需看图。图上有话筒、预加重网络与 VCXO（压控晶振，可以产生调频），说明这是一台 FM 发射机。其余三个选项只出现在接收机里（鉴频器解 FM、CAG 稳增益、silencieux 静噪），可以整组排除。发射链路里还缺的一级是把振荡频率成倍抬高、同时把频偏成倍加大的倍频器，故答倍频器。""",
    "20309": r"""两个信号在非线性器件里混频时会生成一大批和差组合，三阶产物 \(2F_1\pm F_2\) 与 \(F_1\pm 2F_2\) 离有用信号最近，最容易造成干扰。按官方注释图上两频率为 150 MHz 与 145 MHz：\(2\times150-145=155\ \mathrm{MHz}\) 恰在选项中，其余组合 140、440、445 MHz 都不在。300 与 290 MHz 只是二阶产物 \(2F_1\)、\(2F_2\)，属干扰项，把各组合列一遍就不会漏。""",
    "20310": r"""此题需看图。图上解调级是二极管加 RC 的包络检波器（détecteur d'enveloppe），它只跟随信号幅度的起伏，对频率变化并不敏感，因此只能还原 AM。换句话说，它只关心包络的胖瘦，对频率的变化视而不见。听 CW 与 BLU 要另配 BFO 做乘积检波，听 FM 要限幅器加鉴频器，所以这台接收机能收的是调幅信号。""",
    "20311": r"""三环色环中前两环是数字、第三环是倍率，误差环要到第四环才出现。蓝=6、橙=3 组成数字 63，棕=1 即乘 \(10^1\)：\(63\times10=630\ \Omega\)。别把倍率环也当成数字环，否则会连读出 13 MΩ 这类怪值。实际读数要从未端（色环更靠近端部的一侧）开始，顺序反了结果就变。""",
    "20312": r"""蓝=6、黑=0 是前两位数字，组成 60；红=2 是倍率 \(10^2\)，也就是乘 100：\(60\times100=6000\ \Omega=6\ \mathrm{k}\Omega\)。颜色顺序要背牢：黑棕红橙黄绿蓝紫灰白，依次对应 0 到 9。色环按「数字、数字、倍率」的顺序读，第三环不是数字，读错一环就会差十倍。602 Ω 正是把第三环当数字读出来的结果，9 kΩ 与 20 kΩ 与这三色都对不上。""",
    "20313": r"""此题需看图，图上两只电阻是并联（官方按 30 Ω 与 15 Ω 计算）。并联与串联的公式正好相反，动手前先认清接法。并联时两端电压相同、电流各自分流再相加，等效电阻用积比和：\(R_T=\frac{R_1R_2}{R_1+R_2}=\frac{30\times15}{30+15}=\frac{450}{45}=10\ \Omega\)。结果必定小于其中最小的那只（\(10<15\)）；若算得 45 Ω，就是把两值相加当成了串联。""",
    "20314": r"""正弦交流的有效值等于峰值乘 0.707，也就是峰值的 \(1/\sqrt2\)：\(U_{\text{eff}}=0.707\times311\approx220\ \mathrm{V}\)，正是市电标称的 220 V。反过来，峰值是有效值的 1.414 倍，两者只差这一个系数，所以先看清题目给的是峰值还是有效值再决定乘哪一个。439.8 V 是拿 311 再乘 1.414，方向反了；879 V 又把峰值翻了一倍。""",
    "20315": r"""此题需看图，图上是一只 33 Ω 的电阻两端加 12 V。功率 \(P=\frac{U^2}{R}=\frac{12\times12}{33}\approx4.36\ \mathrm{W}\)，标称功率是电阻能长期承受的耗散能力，必须取不小于它的一档，即 5 W。10 W 档当然更保险，但体积大、成本高、寄生参数也大，属于「过大」而不是最小；1 W 与 2 W 会被烧坏，所以只能往上取一档。""",
    "20316": r"""此题需看图，图上基波电压 10 V、三次谐波 1.5 V（另给一个二次谐波的数值作干扰）。n 次谐波失真率是该次谐波电压与基波电压之比，用的是电压比而非功率比：\(\frac{1.5}{10}=0.15\)，即 15%。计算时只取题目指定的那一次谐波，不要与其它次数混算。""",
    "20318": r"""测电压用电压表（voltmètre），并联在被测两点之间，内阻越高对电路影响越小。安培表测电流、必须串入支路，热偶式安培表测的也还是电流；官方注释认为 décibelmètre 与 électromètre 都非通用测量仪器而予排除，于是最合逻辑的就是电压表。""",
    "20320": r"""此题需看图，图上按编号画出各种器件的符号与电极。双极型晶体管（NPN 或 PNP）的三个电极是基极、集电极、发射极，对应题中那一组编号。漏极、源极、栅极（porte）是 FET 的电极，门极（gâchette）与阳极属晶闸管类，认准符号形状再取它标出的编号即可。""",
    "20322": r"""电容的容抗与频率、容量都成反比，频率越高越容易通过：\(Z=\frac{1}{2\pi fC}\)。代入 \(f=5\ \mathrm{MHz}\)、\(C=2\ \mathrm{nF}\)，容抗约 16 Ω；教材简化式 \(Z=\frac{159}{f\cdot C}=159/(5\times2)=15.9\ \Omega\) 更快，f 用 MHz、C 用 nF。容抗不是电阻，它随频率变化且不消耗功率。算完可以复核一下：5 MHz 上的 2 nF 只该有几十欧，628 Ω 差了一个数量级，多是把 nF 当成 pF 算的。""",
    "20325": r"""此题需看图。所标级夹在混频器之后、检波器之前，处在固定频率的选频放大链上，只能叫中频放大器（amplificateur FI），整机大部分增益与选择性都由它提供。射频放大器应在混频器之前，「HF 放大器」这一说法虽不算错但位置与精度都不够；限幅器与 CAG 属于 FM 或增益控制电路。""",
    "20326": r"""此题需看图，图上给出 ROS = 2 和入射功率 9 W。先把驻波比换成反射系数，它是个电压比：\(k=\frac{ROS-1}{ROS+1}=\frac{2-1}{2+1}=\frac13\)，约 0.33。功率按平方关系，故 \(P_{\text{refl}}=9\times0.33^2\approx1\ \mathrm{W}\)。驻波比越接近 1，反射越小、天线匹配越好。常见错误是直接 9 乘 0.33 得 3 W，忘了平方；4.5 W 则是认成一半功率被反射。""",
    "20327": r"""波段名称按波长数量级来定，所以先算波长：\(\lambda=\frac{300}{f(\mathrm{MHz})}=\frac{300}{50}=6\ \mathrm{m}\)，正落在 1~10 m 的米波范围（30~300 MHz，即 VHF）。比它长的是十米波，也就是 décamétriques（10~100 m，3~30 MHz）；比它短的是分米波与厘米波。频率越高波长越短，先算波长再对号就不会错，这题在法规科目里也会考。""",
    "20328": r"""三环电阻的读法是前两环取数字、第三环取倍率。橙=3、黑=0 给出数字 30，第三环黑是 \(10^0=1\)，故 \(30\times1=30\ \Omega\)。这里倍率是 1，所以数值就等于前两位数字本身。300 Ω 是把倍率当成 \(10^1\)，3 Ω 与 0.3 Ω 则把倍率当成了负幂；三环电阻没有误差环，别与四环混淆。""",
    "20331": r"""n 次谐波的频率就是基波频率的 n 倍，乘以基波的那个整数就叫谐波次数，所以二次谐波为 \(2\times2000=4000\ \mathrm{Hz}=4\ \mathrm{kHz}\)。这里有个容易混的说法：「高一个八度」同样是频率乘 2，而「高两个八度」才乘 4，8 kHz 正是按乘 4 设的干扰项。2200 Hz 只比基波略高，1000 Hz 是基波的一半，都不能叫谐波。""",
    "20332": r"""此题需看图。图上是一个简单的单管混频器，载波与音频直接混频，输出是载波加两个边带，即调幅。要产生单边带必须先有平衡混频器以抑制载波，再接石英滤波器（filtre à quartz）取出一个边带、切掉另一个，所以看见简单混频器只能答调幅，不能答 BLU。""",
    "20334": r"""谐振的定义是感抗等于容抗。并联谐振电路（bouchon，即陷波电路）谐振时 L 与 C 的无功电流互相抵消，只剩线圈损耗，所以阻抗很高且近似为纯电阻：\(Z=\frac{L}{RC}\)。图上取 L = 20 µH、C = 100 pF、R = 16 Ω，代入得 12.5 kΩ。答「无穷大」忽略了线圈损耗，16 Ω 则是串联谐振时的结果，两者正好互为对照。""",
    "20335": r"""三环全红的读法：前两环 2、2 组成数字 22，第三环红是倍率 \(10^2\)，也就是乘 100：\(22\times100=2200\ \Omega\)，等于 2.2 kΩ，换成兆欧是 0.0022 MΩ，所以答案是 0.0022 MΩ。用 MΩ 只是把单位放大一百万倍，阻值本身没变。换单位时小数点要数清位数。注意官方注释末尾写成 0,022 MΩ 是笔误，那相当于 22 kΩ。333 Ω 是把三环都当数字连排的错读。""",
    "20338": r"""平行板电容器 \(C=\frac{\varepsilon S}{d}\)：面积与介质材料不变时，减薄介质厚度 d 相当于把两极板拉近，同样电压下可容纳更多电荷，所以容量增大（官方注释在此不完整）。副作用是耐压下降，但极板上的电压由外电路决定，不会因为介质变薄而自行变化。""",
    "20340": r"""此题需看图。标出的位置属于解调级：BLU 信号没有载波，接收时必须由本机补一个载波才能听出话音，这个本振就是 BFO（拍频振荡器），它与乘积检波器（mélangeur de produit）永远成对出现，把中频搬回音频。鉴频器属 FM 解调，CAG 属增益控制，都不在这个位置上。""",
    "20344": r"""增益的单位不同，算 PAR 之前要先把 dBi 换成相对半波偶极子的 dBd：\(4-2.14=1.86\ \mathrm{dBd}\)，对应的倍数 \(10^{0.186}\approx1.53\)。两副同相耦合的天线，增益是在功率上相加的。一副天线的 PAR \(=10\times1.53=15.3\ \mathrm{W}\)，三副同相耦合的八木再乘 3，得 45.9，约 46 W。若把 4 dBi 直接当 4 倍用，就会算出 120 W 的错值，这是本题最大的陷阱。""",
    "20347": r"""FET 是场效应管，三个电极是漏极（drain）、栅极（porte，英文 gate）、源极（source），靠电场控制沟道电流，输入端几乎不取电流。基极、发射极、集电极是双极型晶体管的；阳极、阴极、门极（gâchette）是晶闸管的；一个发射极加两个基极是单结晶体管。还要注意 grille 是电子管栅极的叫法。""",
    "20349": r"""这类题要用三个公式连环计算，先把 Q 与带宽的关系记住会更省时间。第一步算谐振频率，用教材简化式 \(F=\frac{159}{\sqrt{L(\mu\mathrm{H})C(\mathrm{pF})}}\)，把 16 与 100 代入得约 4 MHz。第二步算品质因数 \(Q=\frac{\sqrt{L/C}}{R}=\frac{0.4}{0.02}=20\)，R 取 20 Ω。第三步算带宽 \(B=\frac{F}{Q}=\frac{4000\ \mathrm{kHz}}{20}=200\ \mathrm{kHz}\)。道理是 Q 表示回路储能与每周期损耗之比，损耗越小曲线越尖锐、通带越窄。""",
    "20350": r"""升高一个八度就是把频率乘 2，周期随之减半：\(2000\times2=4000\ \mathrm{Hz}\)。八度是倍数关系而不是加常数，所以 2001 Hz 错；也不是乘 10，乘 10 叫十倍频程。两点之间相差 n 个八度，频率就相差 \(2^n\) 倍，三个八度是 8 倍，八个八度是 256 倍，正好覆盖全部音频范围。""",
    "20353": r"""此题需看图，图上 75 Ω 与 175 Ω 两只电阻串联接在 25 V 上。先合并再算电流，是这类题的关键顺序：串联阻值相加 \(R=75+175=250\ \Omega\)，再由欧姆定律 \(I=\frac{U}{R}=\frac{25}{250}=0.1\ \mathrm{A}=100\ \mathrm{mA}\)，同一支路里两只电阻电流相同，总电压按阻值比例被两只电阻瓜分。333 mA 是用 \(25/75\) 算的，143 mA 是用 \(25/175\) 算的，都漏掉了合并这一步。""",
    "20355": r"""此题需看图，图上两只线圈为 12 µH 与 8 µH。线圈相隔较远、耦合可忽略时，串联电感直接相加：\(12+8=20\ \mu\mathrm{H}\)，因为串联电流相同、磁通互相叠加，感量变大。若并联则用积比和 \(\frac{12\times8}{12+8}=4.8\ \mu\mathrm{H}\)，正好是干扰项。官方注释把「串联」误写成并联，但用的确实是相加。""",
    "20358": r"""三环色环的读法是前两环读数字、第三环读倍率。红=2、黑=0 是前两位数字 20，第三环黑为 \(10^0=1\)，故 \(20\times1=20\ \Omega\)。读实物或图示电阻时要认清方位：从靠近端部色环的那一端开始读，顺序反了数值就不同。200 Ω 是把第三环读成 \(10^1\) 的结果，30 Ω 则是把首环的颜色看错了。""",
    "20359": r"""双极型晶体管由发射极（émetteur）、基极（base）、集电极（collecteur）三个掺杂区、两个 PN 结构成，电子与空穴两种载流子都参与导电，故称「双极」。源极、漏极、栅极是 FET 的电极，阴极、阳极、门极（gâchette）属晶闸管，别张冠李戴；「两个基极」那个说法属于单结晶体管。""",
    "20360": r"""此题需看图，图上给出屏蔽层内径与芯线直径（官方按 10 与 3 计算）。同轴电缆的特性阻抗由尺寸之比决定，与电缆长度无关：\(Z=\frac{138}{\sqrt{\varepsilon}}\log\frac{D}{d}\)。取空气介质 \(\varepsilon=1\)：\(Z=138\times\log\frac{10}{3}\approx72\ \Omega\)。同样尺寸若换成聚乙烯介质（\(\varepsilon=2.3\)），还要除以 1.52，得约 50 Ω，这就是 52 Ω 干扰项的来历。""",
    "20361": r"""此题需看图。图中虽有混频器，却没有本振、也没有中频级，是一张缺件的部分方框图，只能靠位置判断：所标级位于天线与混频器之间，起预选（选频）作用，故选 filtre。检波器应在解调端、音频放大在检波之后、静噪在解调后控制音频通道，都到不了这个位置。""",
    "20362": r"""此题需看图。所标级接在振荡与调制之后、通往天线的路径上，要把信号放大到足够电平，故选射频放大器（ampli RF）。严格说带阻滤波器（filtre réjecteur）也是发射机应有的一级，用于抑制谐波，所以本题有两种都说得通的答案；官方以「没有放大这一级发射机就不工作」为理由取 Ampli RF。""",
    "20365": r"""已知电压和电阻时，用电压的平方除以电阻最省事：\(P=\frac{U^2}{R}\)，代入 12 V 与 220 Ω 得 \(144/220\approx0.6545\ \mathrm{W}\)，即 655 mW，所以该选项是对的。先估数量级也能排除错项：两百多欧上加 12 V，电流约 55 mA，功率自然在 0.5 W 上下。1.528 W 恰好等于 220/144，是把公式上下倒写成 \(R/U^2\) 的结果，这类倒置错误在考场上很常见。""",
    "20368": r"""带宽就是通带两侧各下降 3 dB 处之间的间距。并联谐振频率由 L 与 C 决定：\(F=\frac{159}{\sqrt{L(\mu\mathrm{H})C(\mathrm{pF})}}=\frac{159}{20}\approx8\ \mathrm{MHz}\)（题干把 20 µH 写成 20 H，按 20 H 根本算不出这个值）。带宽 \(B=\frac{F}{Q}=\frac{8\ \mathrm{MHz}}{100}=80\ \mathrm{kHz}\)。道理是 Q 越高能量耗散越慢、曲线越尖锐，通带越窄；中频回路的 Q 通常在几十到一百之间，带宽也就是几十千赫，所以 4 kHz 与 12 kHz 都不成立。""",
    "20370": r"""共发射极接法是基极入、集电极出：输入阻抗中等（约百欧），输出阻抗高（几千欧），电流增益与电压增益都不小，集电极输出与基极输入反相，相移 180°。因此「相移 90°」与「输出阻抗低」错；官方注释把电压增益算作中等而非很高，于是只剩「输入阻抗中等」正确。""",
    "20371": r"""逐条验算：1) \(Q=CU\) 正确，电荷等于容量乘电压。2) 写成 P=UIT 多出一个时间，正确形式是 \(P=UI\)。3) W=UI 少一个时间，正确形式是 \(W=UIt\)。4) I=R/U 分子分母颠倒，应是 \(I=U/R\)。所以四条里只有 1) 对；若把 2)、4) 也算对，就会选到含它们的选项。记住 P 是功率、W 是能量，后者要多乘时间。""",
    "20372": r"""此题需看图。所标级要完成从 AF（音频）到 RF（高频）的转换，也就是用音频去控制高频载波的产生，这一功能叫调制；而调制器的核心就是一个由 LC 回路或石英决定的振荡器（oscillateur）。放大器只放大已有信号，滤波器只选频，混频器只搬移频率，都生不出载波。""",
}
